ALTER TABLE sophonz_traces.sophonz_index_v2 ON CLUSTER '{{.SOPHONZ_CLUSTER}}' ADD COLUMN IF NOT EXISTS sessionSdkV1 LowCardinality(String) MATERIALIZED multiIf(upper(clientPlatform) = 'WEB', 'web', lower(resourceTagsMap['telemetry.sdk.language']) = 'webjs' OR resourceTagsMap['telemetry.sdk.name'] = '@sophonz/browser-sdk', 'web', lower(clientPlatform) IN ('ios','android'), lower(clientPlatform), lower(resourceTagsMap['os.name']) IN ('ios','ipados'), 'ios', lower(resourceTagsMap['os.name']) = 'android','android','');
ALTER TABLE sophonz_traces.distributed_sophonz_index_v2 ON CLUSTER '{{.SOPHONZ_CLUSTER}}' ADD COLUMN IF NOT EXISTS sessionSdkV1 LowCardinality(String) MATERIALIZED multiIf(upper(clientPlatform) = 'WEB', 'web', lower(resourceTagsMap['telemetry.sdk.language']) = 'webjs' OR resourceTagsMap['telemetry.sdk.name'] = '@sophonz/browser-sdk', 'web', lower(clientPlatform) IN ('ios','android'), lower(clientPlatform), lower(resourceTagsMap['os.name']) IN ('ios','ipados'), 'ios', lower(resourceTagsMap['os.name']) = 'android','android','');
ALTER TABLE sophonz_traces.sophonz_index_v2 ON CLUSTER '{{.SOPHONZ_CLUSTER}}' ADD PROJECTION IF NOT EXISTS session_by_sdk_minute_v1 (SELECT serviceNamespace, tenantID, sessionSdkV1, sessionMinuteV1, serviceName, tupleElement(sessionFactsV1, 'sid'), min(toUnixTimestamp64Milli(timestamp)), max(toUnixTimestamp64Milli(timestamp) + durationNano/1e6), maxIf(tuple(toUnixTimestamp64Nano(timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'device'))), notEmpty(tupleElement(sessionFactsV1, 'device'))), maxIf(tuple(toUnixTimestamp64Nano(timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'version'))), notEmpty(tupleElement(sessionFactsV1, 'version'))), maxIf(tuple(toUnixTimestamp64Nano(timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'person'))), notEmpty(tupleElement(sessionFactsV1, 'person'))), maxIf(tuple(toUnixTimestamp64Nano(timestamp), tupleElement(sessionFactsV1, 'eventKey'), toString(tupleElement(sessionFactsV1, 'installation'))), notEmpty(tupleElement(sessionFactsV1, 'installation'))), sum(toUInt64(tupleElement(sessionFactsV1, 'navigation'))), sum(toUInt64(notEmpty(tupleElement(sessionFactsV1, 'route')))), sum(toUInt64(tupleElement(sessionFactsV1, 'request'))), sum(toUInt64(tupleElement(sessionFactsV1, 'failed'))), groupArrayIf(tuple(toUnixTimestamp64Nano(timestamp), tupleElement(sessionFactsV1, 'eventKey'), tupleElement(sessionFactsV1, 'route')), notEmpty(tupleElement(sessionFactsV1, 'route'))) GROUP BY serviceNamespace, tenantID, sessionSdkV1, sessionMinuteV1, serviceName, tupleElement(sessionFactsV1, 'sid'));
